// Install dependencies:
//   npx create-react-app carbon-header-bug
//   cd carbon-header-bug
//   npm install carbon-components carbon-components-react @carbon/icons-react
//   Copy this file into src/index.js

import React from 'react';
import ReactDOM from 'react-dom';
import {
  Header,
  HeaderName,
  HeaderNavigation,
  HeaderMenu,
  HeaderMenuItem,
  HeaderGlobalBar,
  HeaderGlobalAction,
  SkipToContent,
} from 'carbon-components-react';
import { Notification20 } from '@carbon/icons-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  return (
    <>
      {/* This link is always visible and triggers the contrast warning in DAP */}
      <SkipToContent href="#main-content" />

      <Header aria-label="IBM Platform">
        <HeaderName href="/" prefix="IBM">
          Platform
        </HeaderName>

        <HeaderNavigation aria-label="Main navigation">
          {/* Top-level link; in wide view this lives inside a <ul role="menubar"> */}
          <HeaderMenuItem href="/dashboard">Dashboard</HeaderMenuItem>

          {/* Has its own submenu; also lives under the menubar in wide view */}
          <HeaderMenu menuLinkName="Products" aria-label="Products menu">
            <HeaderMenuItem href="/prod/one">Product One</HeaderMenuItem>
            <HeaderMenuItem href="/prod/two">Product Two</HeaderMenuItem>
          </HeaderMenu>
        </HeaderNavigation>

        <HeaderGlobalBar>
          <HeaderGlobalAction aria-label="Notifications" tooltipAlignment="center">
            <Notification20 />
          </HeaderGlobalAction>
        </HeaderGlobalBar>
      </Header>

      <main id="main-content" style={{ padding: '2rem' }}>
        <h1>Main Content Area</h1>
        <p>Resize the window below the nav breakpoint to see the collapsed panel.</p>
      </main>
    </>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
